 *
 *
 * Parse a well-balanced chunk of an XML document
 * called by the parser
 * The allowed sequence for the Well Balanced Chunk is the one defined by
 * the content production in the XML grammar:
 *
 * [43] content ::= (element | CharData | Reference | CDSect | PI | Comment)*
 *
 * Returns XML_ERR_OK if the chunk is well balanced, and the parser
 * error code otherwise
 *
 * In case recover is set to 1, the nodelist will not be empty even if
 * the parsed chunk is not well balanced.
 */
static xmlParserErrors
xmlCtxtParseInternalEntity(xmlParserCtxtPtr ctxt, const xmlChar *string,
                           xmlNodePtr *list) {
    xmlParserInputPtr input;
    xmlNodePtr root;
    unsigned long consumed;

    if (list != NULL)
        *list = NULL;

    if ((ctxt == NULL) || (string == NULL))
        return(XML_ERR_ARGUMENT);

    input = xmlNewStringInputStream(ctxt, string);
    if (input == NULL)
        return(ctxt->errNo);

    root = xmlCtxtParseContent(ctxt, input, 0 /* hasTextDecl */);

    if ((list != NULL) && (root != NULL)) {
        xmlNodePtr cur;

        /*
         * Return the newly created nodeset after unlinking it from
         * their pseudo parent.
         */
        cur = root->children;
        *list = cur;
        while (cur != NULL) {
            cur->parent = NULL;
            cur = cur->next;
        }
        root->children = NULL;
        root->last = NULL;
    }

    /*
     * Also record the size of the entity parsed
     */
    consumed = input->consumed;
    xmlSaturatedAddSizeT(&consumed, input->cur - input->base);

    xmlSaturatedAdd(&ctxt->sizeentcopy, consumed);

    xmlFreeNode(root);
    xmlFreeInputStream(input);

    return(ctxt->errNo);
}

